/* Generated by UI Studio. Structural insertions use stable IDs and run before app.js. */
(() => {
  const insertions = [];
  const find = (id) => id ? document.querySelector(`[data-ui-id="${CSS.escape(id)}"]`) : null;
  const apply = () => {
    for (const insertion of insertions) {
      if (find(insertion.id)) continue;
      const source = find(insertion.sourceId);
      if (!source) continue;
      const parent = find(insertion.parentId) || source.parentElement;
      if (!parent) continue;
      const clone = source.cloneNode(true);
      const mapped = [clone, ...clone.querySelectorAll('[data-ui-id]')];
      for (const element of mapped) {
        const nextId = insertion.idMap[element.dataset.uiId];
        if (nextId) element.dataset.uiId = nextId;
      }
      clone.dataset.uiStudioInsertion = insertion.id;
      if (insertion.name) clone.dataset.uiName = insertion.name;
      const after = find(insertion.afterId);
      if (after?.parentElement === parent) after.after(clone);
      else parent.append(clone);
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply, { once:true });
  else apply();
})();
